543	- [ ] **Step 3: Write the implementation**
544	
545	In `src/textstats.js`, replace the line `module.exports = { wordCount };` with the following block. Everything above that line stays as it is.
546	
547	```javascript
548	// Words whose trailing period does not end a sentence. Compared lower-case and
549	// without any opening bracket or quote. "U.S.A." style initialisms are not
550	// listed: they usually do end a sentence when they come last, and guessing
551	// otherwise would trade one error for another.
552	const ABBREVIATIONS = new Set(['mr', 'mrs', 'ms', 'dr', 'prof', 'st', 'sr', 'jr', 'vs', 'e.g', 'i.e']);
553	
554	// A terminator run ("." "?!" "...") plus any closing quotes or brackets, and
555	// only where whitespace or the end of the text follows. Requiring that keeps
556	// decimals ("3.14"), domains ("example.com") and "a.b.c" in one piece.
557	const TERMINATOR_PATTERN = /([.!?]+)(["'”’)\]]*)(?=\s|$)/g;
558	
559	function endsWithAbbreviation(before) {
560	  const last = before.match(/(\S+)$/);
561	  if (last === null) {
562	    return false;
563	  }
564	  const word = last[1].replace(/^["'“‘(\[]+/, '').toLowerCase();
565	  return ABBREVIATIONS.has(word);
566	}
567	
568	/**
569	 * Count the sentences in a piece of text.
570	 *
571	 * A sentence is a stretch of text containing at least one word and ending at a
572	 * terminator run, or at the end of the text. A lone period after a known
573	 * abbreviation does not end a sentence.
574	 *
575	 * @param {string} text
576	 * @returns {number}
577	 */
578	function sentenceCount(text) {
579	  assertText('sentenceCount', text);
580	  let count = 0;
581	  let start = 0;
582	  for (const match of text.matchAll(TERMINATOR_PATTERN)) {
583	    const before = text.slice(start, match.index);
584	    if (match[1] === '.' && endsWithAbbreviation(before)) {
585	      continue;
586	    }
587	    if (tokenize(before).length > 0) {
588	      count += 1;
589	    }
590	    start = match.index + match[0].length;
591	  }
592	  if (tokenize(text.slice(start)).length > 0) {
593	    count += 1;
594	  }
595	  return count;
596	}
597	
598	module.exports = { wordCount, sentenceCount };
599	```
